// GRADE_v1 (v0.3) - certitude des preuves par outcome (Summary of Findings).
// Consomme les sorties meta-analyse (_meta_summary : I2, IC groupe, Egger, k) et RoB (_rob_level)
// si presentes dans le corpus ; 1 appel LLM pour le caractere indirect (et le risque de biais si pas de RoB).
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const articles = items.map(i => i.json);
const a0 = articles[0] || {};
const QUESTION = (a0.question || a0._meta_outcome || '').toString();
const ms = a0._meta_summary || null;
console.log('[GRADE] ' + articles.length + ' etudes, meta=' + (!!ms) );

function extractJson(raw){ if(!raw) return null; let s=String(raw).replace(/```json/gi,'').replace(/```/g,''); const i=s.indexOf('{'),j=s.lastIndexOf('}'); if(i<0||j<=i) return null; const f=s.substring(i,j+1); try{return JSON.parse(f);}catch(e){} try{return JSON.parse(f.replace(/,\s*([}\]])/g,'$1'));}catch(e){} return null; }
function detectDesign(a){ const t=((a.title||'')+' '+(a.abstract||'')).toLowerCase(); if(/randomi[sz]ed[^.]{0,20}(controlled )?trial|\brct\b|randomi[sz]ed[^.]{0,20}(study|design)|randomly (assigned|allocated)|double-blind|placebo-controlled/.test(t)) return 'rct'; if(/cohort|case-control|case control|observational|cross-sectional|registry|retrospective|prospective (cohort|study)|non-randomi/.test(t)) return 'nonrandomized'; return 'unknown'; }

// devis majoritaire (heuristique ; secours = LLM si tout 'unknown')
let nrct=0,nnr=0; for(const a of articles){ const d=detectDesign(a); if(d==='rct')nrct++; else if(d==='nonrandomized')nnr++; }
let design = (nrct>=nnr && nrct>0) ? 'rct' : (nnr>0 ? 'nonrandomized' : 'unknown');

// signal risque de biais depuis le module RoB si present
let robN=0, robHigh=0; for(const a of articles){ if(a._rob_level){ robN++; if(a._rob_level==='high')robHigh++; } }
const robProp = robN ? robHigh/robN : null;

// 1 appel LLM : caractere indirect (+ risque de biais si pas de donnees RoB)
const titles = articles.map(function(a){return (a.title||'').substring(0,90);}).filter(Boolean).slice(0,8);
let llm = { indirectness:'none', indirectness_reason:'', risk_of_bias:'low', rob_reason:'' };
try {
  const prompt = [
    'You are applying the GRADE approach. Judge the body of evidence answering this question.',
    'QUESTION: ' + QUESTION.substring(0,300),
    'Number of studies: ' + articles.length + '. Predominant design: ' + design + '.',
    'Sample study titles:', titles.join('\n'),
    '',
    'Return STRICT JSON ONLY:',
    '{ "design": "rct" | "nonrandomized", "indirectness": "none" | "serious", "indirectness_reason": "<short>", "risk_of_bias": "low" | "some" | "high", "rob_reason": "<short>" }',
    'design = predominant study design of this body of evidence.',
    'Indirectness = PICO mismatch with the question (different population/intervention/comparator, or only surrogate/indirect outcomes).',
    'risk_of_bias = your overall impression of study quality from the titles/design (used only if no formal RoB data).'
  ].join('\n');
  const rp = await this.helpers.httpRequest({ method:'POST', url:PROXY+'/api/generate', body:JSON.stringify({ model:'qwen2.5:3b', prompt:prompt, stream:false, format:'json', options:{temperature:0,num_predict:300,num_ctx:8192}, keep_alive:'30m', _ultralab_task:'grade', _ultralab_module:'grade' }), headers:{'Content-Type':'application/json'}, json:true, timeout:900000 });
  const p = extractJson((rp&&rp.response)||''); if(p) llm=Object.assign(llm,p);
} catch(e) { console.log('[GRADE] llm err ' + e.message); }

// devis : secours LLM si l'heuristique n'a rien trouve
if (design==='unknown') design = (llm.design==='rct'||llm.design==='nonrandomized') ? llm.design : 'nonrandomized';

const start = (design==='rct') ? 4 : 2;
let downs=0, ups=0; const domains={}; const upNotes=[], upNotesEn=[];
// TOUR 3 du lot « meta-analyse, regroupement et GRADE » (2026-10-20) : CHAQUE TEXTE ECRIT ICI A SON
// CHAMP ANGLAIS, que chaque lecteur lit. CE QUI ETAIT FAUX, MESURE (ce nœud execute sur 20 etats) :
// les notes des cinq domaines, les evaluations « non evaluable ... », la phrase de methode, la taille
// d information, le niveau de depart et les notes de reclassement etaient en francais seul ; trois
// notes et la phrase de methode portaient « francais / English » dans le meme champ, dont l ecran
// GRADE (GradeLive.svelte, 80 caracteres) ne montrait que le francais, ecran anglais compris.
// LA REGLE, celle des autres sorties du produit (note_fr / note_en du resume de meta-analyse) : le
// francais reste dans le champ d origine (`note`, `rating`, `method`, `information_size`,
// `start_level`, `upgrade_notes`), l anglais va dans le champ `_en` ; l ecran lit le champ de sa
// langue (app/src/lib/gradeTextes.ts), le rapport, le classeur et summary-of-findings.html
// (« Assemble Results », workflows/ultralab-module.json) ecrivent les deux. Un texte rendu par le
// modele (raison du risque de biais, du caractere indirect) est repris tel quel dans les deux champs.
// Cas : tests/test_grade_notes_bilingues.py.

// 1. Risque de biais
if (robProp!=null){ const __rn='module RoB : '+robHigh+'/'+robN+' a risque eleve', __rnEn='RoB module: '+robHigh+'/'+robN+' at high risk'; if(robProp>0.5){ domains.risk_of_bias={rating:'serious (-1)',note:__rn,note_en:__rnEn}; downs-=1; } else domains.risk_of_bias={rating:'not serious',note:__rn,note_en:__rnEn}; }
else { if((llm.risk_of_bias||'')==='high'){ domains.risk_of_bias={rating:'serious (-1)',note:'jugement IA : '+(llm.rob_reason||''),note_en:'AI judgement: '+(llm.rob_reason||'')}; downs-=1; } else domains.risk_of_bias={rating:'not serious',note:'jugement IA (pas de run RoB) : '+(llm.rob_reason||''),note_en:'AI judgement (no RoB run): '+(llm.rob_reason||'')}; }

// 2. Incoherence (I2)
if (ms && ms.heterogeneity){ const i2=ms.heterogeneity.I2; if(i2>=50){ domains.inconsistency={rating:'serious (-1)',note:'I2='+i2+'%',note_en:'I2='+i2+'%'}; downs-=1; } else domains.inconsistency={rating:'not serious',note:'I2='+i2+'%',note_en:'I2='+i2+'%'}; }
else domains.inconsistency={rating:'non evaluable',note:'pas de meta-analyse en entree (lancer le module meta-analyse d abord)',note_en:'no meta-analysis as input (run the meta-analysis module first)'};

// 3. Imprecision (IC groupe / nb d etudes)
// TOUR 3 du lot « meta » (2026-10-16) : UNE PROPORTION N'A PAS DE VALEUR NULLE. La meta-analyse
// publie desormais une proportion retrotransformee, sans valeur nulle (`null_value` a null,
// `scale.kind` a « proportion »). MESURE sur quatre etudes a evenements rares (0/50, 0/60, 1/40,
// 2/55) : avant, ce noeud jugeait l'echelle du double arcsinus (« not serious », IC95% [0.053,
// 0.208]) ; la proportion retrotransformee, il retombait sur 0 et declassait pour « IC95% franchit
// le nul [0, 0.034] », un non-sens pour une prevalence. Sans seuil de decision, l'imprecision d'une
// proportion ne se juge pas ici : le domaine est dit non evaluable, sans declassement, et la phrase
// demande de juger la largeur de l'IC. La regle sur le nombre d'etudes (k < 4) s'applique toujours.
const __proportion = !!(ms && ms.scale);   // le resume ne porte `scale` que pour une proportion
if (ms && ms.random){ const lo=ms.random.ci_low, hi=ms.random.ci_high, nv=(ms.null_value!=null?ms.null_value:(ms.is_log?1:0)); const crosses=!__proportion && (lo<=nv && hi>=nv); if(crosses){ domains.imprecision={rating:'serious (-1)',note:'IC95% franchit le nul ['+lo+', '+hi+']',note_en:'95% CI crosses the null ['+lo+', '+hi+']'}; downs-=1; } else if((ms.k||0)<4){ domains.imprecision=(ms.k!=null)?{rating:'serious (-1)',note:'peu d etudes (k='+ms.k+')',note_en:'few studies (k='+ms.k+')'}:{rating:'serious (-1)',note:'peu d etudes (k non transmis : la regle k<4 s applique par prudence)',note_en:'few studies (k not transmitted: the k<4 rule applies by caution)'}; downs-=1; } else if(__proportion){ domains.imprecision={rating:'non evaluable',note:'proportion : aucune valeur nulle \u00e0 franchir, jugez la largeur de l\'IC95% ['+lo+', '+hi+'] (k='+ms.k+')',note_en:'proportion: no null value to cross, judge the width of the 95% CI ['+lo+', '+hi+'] (k='+ms.k+')'}; } else domains.imprecision={rating:'not serious',note:'IC95% ['+lo+', '+hi+'], k='+ms.k,note_en:'95% CI ['+lo+', '+hi+'], k='+ms.k}; }
else domains.imprecision={rating:'non evaluable',note:'pas de meta-analyse en entree',note_en:'no meta-analysis as input'};
// TOUR 3 : k NON TRANSMIS. La note ecrivait « peu d etudes (k=undefined) ». Le declassement est garde
// (decision prudente, signalee a l auteur : la regle k<4 s applique comme a k = 0) et la note le dit.
// J4 : TAILLE D'INFORMATION OPTIMALE, en COMMENTAIRE et non en declassement.
// GRADE demande de se demander si le corpus atteint la taille qu'exigerait la question. On
// l'expose donc, mais on NE TOUCHE PAS a `downs` : un declassement automatique sur un seuil
// forfaitaire punirait a tort des corpus parfaitement valables, et ce depot considere qu'un
// garde-fou qui se declenche a tort coute plus cher que le defaut qu'il surveille.
// Le seuil de 400 participants est une regle de POUCE usuelle pour un critere continu ; elle
// ne remplace pas un calcul d'effectif fonde sur un effet plausible, et le texte le dit.
if (ms && ms.participants) {
  var _p = ms.participants || {};
  if (_p.total == null) {
    domains.imprecision = domains.imprecision || {};
    domains.imprecision.information_size = 'effectifs non renseignes dans les etudes : taille d information non evaluable';
    domains.imprecision.information_size_en = 'sample sizes not reported in the studies: information size not assessable';
  } else {
    var _partiel = (_p.k_avec_effectif < _p.k_total)
      ? (' (sur ' + _p.k_avec_effectif + ' etudes sur ' + _p.k_total + ' seulement)') : '';
    var _partielEn = (_p.k_avec_effectif < _p.k_total)
      ? (' (for ' + _p.k_avec_effectif + ' of ' + _p.k_total + ' studies only)') : '';
    domains.imprecision = domains.imprecision || {};
    domains.imprecision.participants = _p.total;
    // P20 (2026-10-20) : BRANCHE RENDUE ATTEIGNABLE. La meta-analyse compte desormais l'effectif d'une
    // proportion ; le repere de 400 participants vaut pour un critere continu, pas pour une
    // proportion : il n'est pas applique, et la phrase le dit en francais et en anglais.
    if (__proportion) {
      domains.imprecision.information_size = _p.total + ' participants' + _partiel + ' (somme des effectifs des etudes) : le repere usuel de 400 vaut pour un critere continu, pas pour une proportion ; jugez la largeur de l IC95%. Ce reperage n entraine aucun declassement automatique.';
      domains.imprecision.information_size_en = _p.total + ' participants' + _partielEn + ' (sum of the study sample sizes): the usual benchmark of 400 applies to a continuous outcome, not to a proportion; judge the width of the 95% CI. This check triggers no automatic downgrade.';
    } else if (_p.total < 400) {
      domains.imprecision.information_size = 'a verifier : ' + _p.total + ' participants' + _partiel + ', en deca du repere usuel de 400 pour un critere continu. Verifiez la taille d information optimale a partir d un effet plausible ; ce reperage n entraine AUCUN declassement automatique.';
      domains.imprecision.information_size_en = 'to check: ' + _p.total + ' participants' + _partielEn + ', below the usual benchmark of 400 for a continuous outcome. Check the optimal information size from a plausible effect; this check triggers NO automatic downgrade.';
    } else {
      domains.imprecision.information_size = _p.total + ' participants' + _partiel + ', au-dela du repere usuel de 400. Ce reperage n entraine aucun declassement automatique.';
      domains.imprecision.information_size_en = _p.total + ' participants' + _partielEn + ', above the usual benchmark of 400. This check triggers no automatic downgrade.';
    }
  }
}

// 4. Caractere indirect (LLM)
if ((llm.indirectness||'')==='serious'){ domains.indirectness={rating:'serious (-1)',note:llm.indirectness_reason||'jugement IA (PICO vs question)',note_en:llm.indirectness_reason||'AI judgement (PICO vs question)'}; downs-=1; }
else domains.indirectness={rating:'not serious',note:llm.indirectness_reason||'jugement IA (PICO vs question)',note_en:llm.indirectness_reason||'AI judgement (PICO vs question)'};

// 5. Biais de publication (test d Egger, seulement si k>=10)
// Garde-fou Cochrane (Handbook, evaluation des biais de publication) : le test d Egger n a pas de
// puissance en dessous de 10 etudes et ne doit pas y etre interprete. Sous ce seuil, aucun
// declassement n est applique et l etat « non evaluable (k<10) » apparait dans le tableau GRADE,
// pour que l absence de declassement soit visible et justifiee plutot que silencieuse.
// AUCUN ORGANISME N EST NOMME DANS CE QUI EST ECRIT (2026-10-20, decision de l auteur du
// 2026-10-19, deja appliquee au gabarit R). CE QUI ETAIT FAUX : la phrase de methode (PB_METHOD,
// ecrite dans chaque etat du domaine) et les notes « k inconnu » et « k < 10 » disaient « regle
// Cochrane » ; elles partent telles quelles au rapport, au classeur, a summary-of-findings.html et
// a l ecran. MESURE (base e332a31, nœud execute) : sept etats sur sept nommaient l organisme. La
// regle reste dite (k>=10, « sous 10 etudes ») ; seul ce commentaire en cite la source.
// TOUR 2 (2026-10-20, verification du tour 1) : CES TROIS TEXTES ETAIENT EN FRANCAIS SEUL. Ils
// partent tels quels a l ecran (GradeLive.svelte affiche `note` sans traduction, ecran anglais
// compris), au rapport, au classeur et a summary-of-findings.html. Ils sont ecrits desormais
// « francais / English », comme la phrase de la proportion (domaine imprecision) ; le francais
// reste en tete, l ecran n en montrant que les 80 premiers caracteres.
// TOUR 3 (2026-10-20) : le francais et l anglais sont separes, `method` / `method_en` et `note` /
// `note_en` (voir le commentaire du TOUR 3 plus haut) ; l ecran montre la langue de l ecran.
// Cas : tests/test_avertissement_k10_grade_sans_organisme.py.
const EGGER_K_MIN = 10;
const kPub = (ms && ms.k!=null) ? ms.k : null;
const PB_METHOD = 'test d Egger (regression de l asymetrie du funnel), juge contre la valeur critique de Student a n-2 ddl (bilateral 95%), interprete seulement si k>=' + EGGER_K_MIN;
const PB_METHOD_EN = 'Egger test (regression of funnel plot asymmetry), judged against the Student critical value with n-2 df (two-sided 95%), interpreted only if k>=' + EGGER_K_MIN;
if (!ms) domains.publication_bias={rating:'non evaluable',note:'pas de meta-analyse en entree',note_en:'no meta-analysis as input',method:PB_METHOD,method_en:PB_METHOD_EN};
else if (kPub==null) domains.publication_bias={rating:'non evaluable (k inconnu)',note:'nombre d etudes non transmis : test d Egger non interpretable (regle : k>='+EGGER_K_MIN+'), aucun declassement',note_en:'number of studies not transmitted: Egger test not interpretable (rule: k>='+EGGER_K_MIN+'), no downgrade',method:PB_METHOD,method_en:PB_METHOD_EN};
else if (kPub<EGGER_K_MIN) domains.publication_bias={rating:'non evaluable (k<'+EGGER_K_MIN+')',note:'k='+kPub+' (<'+EGGER_K_MIN+') : test d Egger non interpretable sous '+EGGER_K_MIN+' etudes, aucun declassement'+(ms.egger?(' ; t exploratoire='+ms.egger.t):' ; test non calcule'),note_en:'k='+kPub+' (<'+EGGER_K_MIN+'): Egger test not interpretable under '+EGGER_K_MIN+' studies, no downgrade'+(ms.egger?('; exploratory t='+ms.egger.t):'; test not computed'),method:PB_METHOD,method_en:PB_METHOD_EN};
else if (ms.egger){
  // A8 : LA VALEUR CRITIQUE EST CELLE DE STUDENT, PAS 1,96. Le test d Egger est une regression
  // a n-2 degres de liberte ; 1,96 est le quantile NORMAL, c est-a-dire la limite atteinte a
  // effectif infini. Sur les tailles reelles d une meta-analyse la difference est loin d etre
  // negligeable : 2,306 a k=10, 2,228 a k=12, 2,160 a k=15, 2,101 a k=20, 2,048 a k=30. Entre
  // 1,96 et cette valeur, la certitude etait declassee d un cran sans qu aucun seuil ne soit
  // franchi. La valeur est CALCULEE PAR LA META-ANALYSE et voyage avec le t : on ne recopie
  // pas ici une seconde fonction de quantile, qui divergerait de la premiere.
  const t=Math.abs(ms.egger.t||0);
  const tcrit=(typeof ms.egger.t_critique==='number' && ms.egger.t_critique>0)?ms.egger.t_critique:null;
  const dl=(ms.egger.df!=null)?(', ' + ms.egger.df + ' ddl'):'';
  const dlEn=(ms.egger.df!=null)?(', ' + ms.egger.df + ' df'):'';
  if (tcrit==null){
    // Meta-analyse produite par une version anterieure : la valeur critique n est pas connue.
    // On ne declasse PAS sur un seuil qu on sait faux, et on dit pourquoi.
    domains.publication_bias={rating:'non evaluable (valeur critique absente)',
      note:'test d Egger t='+ms.egger.t+dl+' mais la meta-analyse ne transmet pas la valeur critique de Student : aucun declassement, relancez la meta-analyse pour trancher',
      note_en:'Egger test t='+ms.egger.t+dlEn+' but the meta-analysis does not transmit the Student critical value: no downgrade, rerun the meta-analysis to decide',
      method:PB_METHOD, method_en:PB_METHOD_EN};
  } else if(t>=tcrit){
    domains.publication_bias={rating:'suspected (-1)',
      note:'test d Egger t='+ms.egger.t+' >= '+tcrit+' (valeur critique de Student'+dl+', bilateral 95% ; k='+kPub+' >= '+EGGER_K_MIN+', interpretable) : asymetrie du funnel',
      note_en:'Egger test t='+ms.egger.t+' >= '+tcrit+' (Student critical value'+dlEn+', two-sided 95%; k='+kPub+' >= '+EGGER_K_MIN+', interpretable): funnel asymmetry',
      method:PB_METHOD, method_en:PB_METHOD_EN};
    downs-=1;
  } else {
    domains.publication_bias={rating:'undetected',
      note:'test d Egger t='+ms.egger.t+' < '+tcrit+' (valeur critique de Student'+dl+', bilateral 95% ; k='+kPub+' >= '+EGGER_K_MIN+', interpretable) : pas d asymetrie detectee',
      note_en:'Egger test t='+ms.egger.t+' < '+tcrit+' (Student critical value'+dlEn+', two-sided 95%; k='+kPub+' >= '+EGGER_K_MIN+', interpretable): no asymmetry detected',
      method:PB_METHOD, method_en:PB_METHOD_EN};
  }
}
else domains.publication_bias={rating:'non evaluable',note:'k='+kPub+' mais test d Egger non calcule par la meta-analyse',note_en:'k='+kPub+' but Egger test not computed by the meta-analysis',method:PB_METHOD,method_en:PB_METHOD_EN};

// Reclassement (observationnel uniquement, effet large)
// A9 : LE RECLASSEMENT NE VAUT QUE POUR UN CORPS DE PREUVES QUI N A ETE DECLASSE POUR AUCUN
// DOMAINE. La regle GRADE est explicite : on ne remonte la certitude d etudes observationnelles
// que si elles ne presentent AUCUNE limitation serieuse. La branche ajoutait deux crans sans
// jamais consulter les declassements deja decides.
// MESURE sur ce nœud : trois cohortes marquees a risque de biais eleve, donc risk_of_bias
// serieux (-1), rendaient « moderate » a OR 6 et « very low » a OR 1,4. Deux crans d ecart
// produits par la seule taille de l effet, sur un corpus que le module de risque de biais juge
// mauvais. Un lecteur voyait « certitude moderee » sur des etudes jugees mauvaises.
if (design==='nonrandomized' && ms && ms.random && ms.is_log){
  const e=ms.random.effect;
  var __ampleur=0, __libelle='', __libelleEn='';
  if(e>0){
    if(e<0.2||e>5){ __ampleur=2; __libelle='effet tres large (RR/OR '+e+')'; __libelleEn='very large effect (RR/OR '+e+')'; }
    else if(e<0.5||e>2){ __ampleur=1; __libelle='effet large (RR/OR '+e+')'; __libelleEn='large effect (RR/OR '+e+')'; }
  }
  if(__ampleur>0){
    if(downs===0){
      ups+=__ampleur;
      upNotes.push(__libelle+' : reclassement de +'+__ampleur+' applique, aucun domaine n etant declasse');
      upNotesEn.push(__libelleEn+': upgrade of +'+__ampleur+' applied, no domain being downgraded');
    } else {
      // On NE TAIT PAS le fait que l effet est large : on dit qu il ne suffit pas.
      upNotes.push(__libelle+' : reclassement de +'+__ampleur+' NON applique, le corps de preuves est deja declasse de '+(-downs)+' cran(s) ; la regle GRADE ne remonte la certitude que pour des etudes observationnelles sans limitation serieuse');
      upNotesEn.push(__libelleEn+': upgrade of +'+__ampleur+' NOT applied, the body of evidence is already downgraded by '+(-downs)+' level(s); the GRADE rule only raises certainty for observational studies without serious limitation');
    }
  }
}

// TOUR 3 : l evaluation de chaque domaine en anglais (`rating_en`). Les evaluations francaises
// (« non evaluable ... ») ont leur traduction ; les autres sont deja les termes anglais de GRADE.
// TOUR 4b (2026-10-21) : les lecteurs d Assemble Results (classeur, page, rapport) donnent a ces
// termes anglais leur francais ; ils restent ici en anglais. Correction du 2026-10-24 : seuls
// « pas serieux » et « serieux (-1) » sont les mots de l ecran GRADE ; « suspecte (-1) » et « non
// detecte » traduisent les termes du noeud pour le biais de publication, que l ecran range sous ses
// libelles « Serieux » (-1) et « Pas serieux » (parseSeverity de GradeLive.svelte).
// `rating` ne change pas : l ecran y lit le declassement (parseSeverity de GradeLive.svelte).
const RATING_EN = { 'non evaluable': 'not assessable', 'non evaluable (k inconnu)': 'not assessable (k unknown)',
  'non evaluable (valeur critique absente)': 'not assessable (critical value missing)' };
RATING_EN['non evaluable (k<' + EGGER_K_MIN + ')'] = 'not assessable (k<' + EGGER_K_MIN + ')';
for (const __cle of Object.keys(domains)) {
  const __r = String(domains[__cle].rating || '');
  domains[__cle].rating_en = Object.prototype.hasOwnProperty.call(RATING_EN, __r) ? RATING_EN[__r] : __r;
}
let lvl=start+downs+ups; if(lvl<1)lvl=1; if(lvl>4)lvl=4;
const certaintyMap={4:'high',3:'moderate',2:'low',1:'very low'};
const certaintyFr={high:'Élevée',moderate:'Modérée',low:'Faible','very low':'Très faible'};
const certainty=certaintyMap[lvl];

// TOUR 4 du lot « meta » (2026-10-17) : LA MESURE D'UNE PROPORTION RETROTRANSFORMEE EST « Proportion ».
// `measure` recopiait « PFT » (l'echelle du calcul) a cote de `pooled`, retrotransforme : MESURE sur
// trois etudes a 12/80, 20/90 et 9/70, summary-of-findings.html publiait « effet groupe PFT 0.168
// [0.117, 0.226] » et ses colonnes XLSX « mesure PFT ». Seul le resume d'une proportion
// retrotransformee porte `scale` ; un run de meta ecrit avant le tour 3 garde « PFT », sur son echelle.
a0._grade_summary = {
  outcome: (ms&&ms.outcome) || QUESTION || '(outcome principal)',
  // TOUR 4 (2026-10-21) : le repli a son anglais ; un outcome lu (critere de la meta-analyse,
  // question) est le meme dans les deux champs. Cas : tests/test_grade_cadre_bilingue.py.
  outcome_en: (ms&&ms.outcome) || QUESTION || '(primary outcome)',
  design: design,
  start_level: (design==='rct')?'Élevée (ECR)':'Faible (observationnel)',
  start_level_en: (design==='rct')?'High (RCT)':'Low (observational)',
  downgrades: -downs, upgrades: ups,
